                disabled={isLoading}
                className="absolute right-2 top-1.5 p-1.5 text-red-600 hover:text-red-700 disabled:opacity-50"
              >
                <Send className="w-5 h-5" />
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

